inline int genieQueryDistance(int x,int y,int radius,const GenieVisibleRecord &record) {
    if(radius<0)return -1;
    radius=std::min(radius,15);
    if(x<-(radius+7) || y<-(radius+7) || x>255+radius+7 || y>255+radius+7)return -1;
    const int dx=std::abs(int(record.x)-x),dy=std::abs(int(record.y)-y);
    if(dx>radius+7 || dy>radius+7)return -1;
    int distance=genieQueryDistances[size_t(dx&31)+32*size_t(dy&31)];
    if(distance>radius) {
        distance-=record.radius;
        if(distance>radius)return -1;
        if(distance<=0)distance=1;
    }
    return distance;
}
inline int genieTargetQueryRadius(float search,float sight) {
    if(!std::isfinite(search) || !std::isfinite(sight))return 0;
    return std::max(int(std::clamp(search,0.f,15.f)),int(std::clamp(sight,0.f,14.f))+1);
}
inline uint8_t genieDiplomacyPartition(int viewer,int owner,unsigned stance) {
    return owner==0?0:owner==viewer?1:stance==0?2:stance==1?3:4;
}
